@startuml

class Customer {
  + Name : string
  + Email : string
}

class InsurancePolicy {
  + Type : string
  + CoverageDetails : string
}

class Contract {
  + PolicyId : int
  + StartDate : date
  + EndDate : date
  + PremiumAmount : double
}

class Invoice {
  + InvoiceNumber : int
  + IssueDate : date
  + DueDate : date
  + TotalAmount : double
}

class Payment {
  + PaymentId : int
  + PaymentDate : date
  + Amount : double
}

Customer "1" -- "*" Contract
Contract "1" -- "1" InsurancePolicy
Customer "0..*" -- "0..1" Invoice
Invoice "1" -- "*" Payment

@enduml

